function writeRunePart(w: Writer, v: RunePart): void {
  switch (v.type) {
    case "Line":
      w.variant(0);
      return;
    case "Pool":
      w.variant(1);
      writeElement(w, v.element);
      return;
    case "Well":
      w.variant(2);
      writeElement(w, v.element);
      return;
    case "Stone":
      w.variant(3);
      return;
    case "Socket":
      w.variant(4);
      w.option(v.word, (x) => w.u16(x));
      return;
    case "Core":
      w.variant(5);
      return;
    case "OldStone":
      w.variant(6);
      return;
    case "OldSocket":
      w.variant(7);
      w.option(v.word, (x) => w.u16(x));
      return;
    default:
      throw invalidVariant("RunePart", v);
  }
}

function readRunePart(r: Reader): RunePart {
  const variant = r.variant();
  switch (variant) {
    case 0:
      return { type: "Line" };
    case 1:
      return {
        type: "Pool",
        element: readElement(r),
      };
    case 2:
      return {
        type: "Well",
        element: readElement(r),
      };
    case 3:
      return { type: "Stone" };
    case 4:
      return {
        type: "Socket",
        word: r.option(() => r.u16()),
      };
    case 5:
      return { type: "Core" };
    case 6:
      return { type: "OldStone" };
    case 7:
      return {
        type: "OldSocket",
        word: r.option(() => r.u16()),
      };
    default:
      throw r.unknownVariant("RunePart");
  }
}

