function writePartShape(w: Writer, v: PartShape): void {
  switch (v.type) {
    case "Box":
      w.variant(0);
      writeModelVec(w, v.from);
      writeModelVec(w, v.to);
      return;
    case "Cylinder":
      w.variant(1);
      writeModelVec(w, v.center);
      writeModelAxis(w, v.axis);
      w.fixed(v.radius);
      w.fixed(v.length);
      w.u32(v.sides);
      w.option(v.cap, (x) => writeModelMaterial(w, x));
      return;
    case "Gear":
      w.variant(2);
      writeModelVec(w, v.center);
      writeModelAxis(w, v.axis);
      w.fixed(v.outer);
      w.fixed(v.root);
      w.u32(v.teeth);
      w.fixed(v.length);
      return;
    case "Ring":
      w.variant(3);
      writeModelVec(w, v.center);
      writeModelAxis(w, v.axis);
      w.fixed(v.inner);
      w.fixed(v.outer);
      w.fixed(v.length);
      w.u32(v.sides);
      return;
    case "Prism":
      w.variant(4);
      writeModelVec(w, v.center);
      writeModelAxis(w, v.axis);
      w.vec(v.radii, (x) => w.fixed(x));
      w.fixed(v.length);
      w.option(v.cap, (x) => writeModelMaterial(w, x));
      return;
    case "Frustum":
      w.variant(5);
      writeModelVec(w, v.center);
      w.fixed(v.height);
      w.fixed(v.bottom);
      w.fixed(v.top);
      return;
    case "Wedge":
      w.variant(6);
      writeModelVec(w, v.from);
      writeModelVec(w, v.to);
      w.option(v.cap, (x) => writeModelMaterial(w, x));
      return;
    default:
      throw invalidVariant("PartShape", v);
  }
}

function readPartShape(r: Reader): PartShape {
  const variant = r.variant();
  switch (variant) {
    case 0:
      return {
        type: "Box",
        from: readModelVec(r),
        to: readModelVec(r),
      };
    case 1:
      return {
        type: "Cylinder",
        center: readModelVec(r),
        axis: readModelAxis(r),
        radius: r.fixed(),
        length: r.fixed(),
        sides: r.u32(),
        cap: r.option(() => readModelMaterial(r)),
      };
    case 2:
      return {
        type: "Gear",
        center: readModelVec(r),
        axis: readModelAxis(r),
        outer: r.fixed(),
        root: r.fixed(),
        teeth: r.u32(),
        length: r.fixed(),
      };
    case 3:
      return {
        type: "Ring",
        center: readModelVec(r),
        axis: readModelAxis(r),
        inner: r.fixed(),
        outer: r.fixed(),
        length: r.fixed(),
        sides: r.u32(),
      };
    case 4:
      return {
        type: "Prism",
        center: readModelVec(r),
        axis: readModelAxis(r),
        radii: r.vec(() => r.fixed()),
        length: r.fixed(),
        cap: r.option(() => readModelMaterial(r)),
      };
    case 5:
      return {
        type: "Frustum",
        center: readModelVec(r),
        height: r.fixed(),
        bottom: r.fixed(),
        top: r.fixed(),
      };
    case 6:
      return {
        type: "Wedge",
        from: readModelVec(r),
        to: readModelVec(r),
        cap: r.option(() => readModelMaterial(r)),
      };
    default:
      throw r.unknownVariant("PartShape");
  }
}

