function writeCreatureInfo(w: Writer, v: CreatureInfo): void {
  w.string(v.name);
  writeCreatureTier(w, v.tier);
  w.string(v.model);
  w.option(v.body, (x) => writeCreatureBody(w, x));
  writeCreatureMoves(w, v.moves);
  w.option(v.health, (x) => w.u32(x));
  w.option(v.group, (x) => writeCreatureGroup(w, x));
  w.option(v.habitat, (x) => writeCreatureHabitat(w, x));
  w.option(v.ambient, (x) => writeCreatureAmbient(w, x));
  w.vec(v.behaviors, (x) => writeCreatureBehavior(w, x));
  w.option(v.tame, (x) => writeCreatureTame(w, x));
  w.vec(v.drops, (x) => writeCreatureDrop(w, x));
  w.option(v.voice, (x) => writeCreatureVoice(w, x));
  w.fixed(v.scaleMin);
  w.fixed(v.scaleMax);
  w.vec(v.tints, (x) => writeCreatureTint(w, x));
  w.u32(v.tough);
  w.bool(v.kin);
  w.option(v.keep, (x) => writeCreatureKeep(w, x));
  w.option(v.fight, (x) => writeCreatureFight(w, x));
  w.vec(v.birthplaces, (x) => writeCreatureBirthplace(w, x));
}

function readCreatureInfo(r: Reader): CreatureInfo {
  return {
    name: r.string(),
    tier: readCreatureTier(r),
    model: r.string(),
    body: r.option(() => readCreatureBody(r)),
    moves: readCreatureMoves(r),
    health: r.option(() => r.u32()),
    group: r.option(() => readCreatureGroup(r)),
    habitat: r.option(() => readCreatureHabitat(r)),
    ambient: r.option(() => readCreatureAmbient(r)),
    behaviors: r.vec(() => readCreatureBehavior(r)),
    tame: r.option(() => readCreatureTame(r)),
    drops: r.vec(() => readCreatureDrop(r)),
    voice: r.option(() => readCreatureVoice(r)),
    scaleMin: r.fixed(),
    scaleMax: r.fixed(),
    tints: r.vec(() => readCreatureTint(r)),
    tough: r.u32(),
    kin: r.bool(),
    keep: r.option(() => readCreatureKeep(r)),
    fight: r.option(() => readCreatureFight(r)),
    birthplaces: r.vec(() => readCreatureBirthplace(r)),
  };
}

