function writeCreatureBehavior(w: Writer, v: CreatureBehavior): void {
  switch (v.type) {
    case "Flee":
      w.variant(0);
      w.vec(v.from, (x) => w.string(x));
      w.fixed(v.radius);
      w.fixed(v.alertRadius);
      w.fixed(v.panicSeconds);
      return;
    case "Approach":
      w.variant(1);
      w.vec(v.items, (x) => writeNameId(w, x));
      w.fixed(v.radius);
      w.fixed(v.stop);
      return;
    case "Graze":
      w.variant(2);
      w.fixed(v.minSeconds);
      w.fixed(v.maxSeconds);
      return;
    case "Wander":
      w.variant(3);
      return;
    case "Seek":
      w.variant(4);
      w.option(v.heat, (x) => w.u32(x));
      w.vec(v.blocks, (x) => writeNameId(w, x));
      w.fixed(v.radius);
      return;
    case "Drift":
      w.variant(5);
      w.bool(v.wind);
      w.option(v.circle, (x) => w.fixed(x));
      return;
    default:
      throw invalidVariant("CreatureBehavior", v);
  }
}

function readCreatureBehavior(r: Reader): CreatureBehavior {
  const variant = r.variant();
  switch (variant) {
    case 0:
      return {
        type: "Flee",
        from: r.vec(() => r.string()),
        radius: r.fixed(),
        alertRadius: r.fixed(),
        panicSeconds: r.fixed(),
      };
    case 1:
      return {
        type: "Approach",
        items: r.vec(() => readNameId(r)),
        radius: r.fixed(),
        stop: r.fixed(),
      };
    case 2:
      return {
        type: "Graze",
        minSeconds: r.fixed(),
        maxSeconds: r.fixed(),
      };
    case 3:
      return { type: "Wander" };
    case 4:
      return {
        type: "Seek",
        heat: r.option(() => r.u32()),
        blocks: r.vec(() => readNameId(r)),
        radius: r.fixed(),
      };
    case 5:
      return {
        type: "Drift",
        wind: r.bool(),
        circle: r.option(() => r.fixed()),
      };
    default:
      throw r.unknownVariant("CreatureBehavior");
  }
}

