function writeRecallStep(w: Writer, v: RecallStep): void {
  switch (v.type) {
    case "Began":
      w.variant(0);
      w.u32(v.ms);
      return;
    case "Broken":
      w.variant(1);
      writeRecallBreak(w, v.why);
      return;
    case "Arrived":
      w.variant(2);
      writeEntityPos(w, v.home);
      return;
    default:
      throw invalidVariant("RecallStep", v);
  }
}

function readRecallStep(r: Reader): RecallStep {
  const variant = r.variant();
  switch (variant) {
    case 0:
      return {
        type: "Began",
        ms: r.u32(),
      };
    case 1:
      return {
        type: "Broken",
        why: readRecallBreak(r),
      };
    case 2:
      return {
        type: "Arrived",
        home: readEntityPos(r),
      };
    default:
      throw r.unknownVariant("RecallStep");
  }
}

