function writeMachineStatus(w: Writer, v: MachineStatus): void {
  switch (v.type) {
    case "Running":
      w.variant(0);
      return;
    case "Idle":
      w.variant(1);
      return;
    case "Stalled":
      w.variant(2);
      writeStallCause(w, v.cause);
      return;
    default:
      throw invalidVariant("MachineStatus", v);
  }
}

function readMachineStatus(r: Reader): MachineStatus {
  const variant = r.variant();
  switch (variant) {
    case 0:
      return { type: "Running" };
    case 1:
      return { type: "Idle" };
    case 2:
      return {
        type: "Stalled",
        cause: readStallCause(r),
      };
    default:
      throw r.unknownVariant("MachineStatus");
  }
}

