function writeTreeView(w: Writer, v: TreeView): void {
  writePlayerId(w, v.owner);
  w.u8(v.stage);
  w.vec(v.bars, (x) => writeLinearAmount(w, x));
  w.vec(v.notches, (x) => w.fixed(x));
  w.fixed(v.full);
  writeLinearAmount(w, v.health);
  w.u16(v.buds);
  w.u16(v.ripe);
  w.u16(v.eaten);
  w.option(v.next, (x) => w.u64(x));
  w.vec(v.mana, (x) => writeNameId(w, x));
  w.vec(v.fruit, (x) => writeNameId(w, x));
  w.u16(v.reach);
  w.vec(v.trusted, (x) => w.string(x));
  w.fixed(v.appetite);
  w.fixed(v.keeps);
  w.fixed(v.crown);
  w.vec(v.crowns, (x) => w.fixed(x));
}

function readTreeView(r: Reader): TreeView {
  return {
    owner: readPlayerId(r),
    stage: r.u8(),
    bars: r.vec(() => readLinearAmount(r)),
    notches: r.vec(() => r.fixed()),
    full: r.fixed(),
    health: readLinearAmount(r),
    buds: r.u16(),
    ripe: r.u16(),
    eaten: r.u16(),
    next: r.option(() => r.u64()),
    mana: r.vec(() => readNameId(r)),
    fruit: r.vec(() => readNameId(r)),
    reach: r.u16(),
    trusted: r.vec(() => r.string()),
    appetite: r.fixed(),
    keeps: r.fixed(),
    crown: r.fixed(),
    crowns: r.vec(() => r.fixed()),
  };
}

function writePoolView(w: Writer, v: PoolView): void {
  writeElement(w, v.element);
  writeNameId(w, v.mana);
  writeLinearAmount(w, v.amount);
  w.u32(v.cap);
  w.fixed(v.inRate);
  w.fixed(v.outRate);
  w.vec(v.users, (x) => writePoolUser(w, x));
}

function readPoolView(r: Reader): PoolView {
  return {
    element: readElement(r),
    mana: readNameId(r),
    amount: readLinearAmount(r),
    cap: r.u32(),
    inRate: r.fixed(),
    outRate: r.fixed(),
    users: r.vec(() => readPoolUser(r)),
  };
}

function writePoolUser(w: Writer, v: PoolUser): void {
  writeBlockPos(w, v.pos);
  w.bool(v.eats);
  w.u8(v.level);
}

function readPoolUser(r: Reader): PoolUser {
  return {
    pos: readBlockPos(r),
    eats: r.bool(),
    level: r.u8(),
  };
}

function writeFrameView(w: Writer, v: FrameView): void {
  w.string(v.name);
  writeFrameKind(w, v.kind);
  w.u8(v.size);
  w.u8(v.rotation);
  writeBlockPos(w, v.origin);
  writeBlockPos(w, v.key);
  w.vec(v.sockets, (x) => w.option(x, (x1) => w.string(x1)));
  w.vec(v.reads, (x) => w.string(x));
  w.vec(v.fizzles, (x) => writeFizzled(w, x));
  writeFrameStatus(w, v.status);
  writeElement(w, v.element);
  w.fixed(v.rate);
  w.option(v.pool, (x) => writeBlockPos(w, x));
  w.option(v.owner, (x) => writePlayerId(w, x));
  w.u32(v.delay);
}

function readFrameView(r: Reader): FrameView {
  return {
    name: r.string(),
    kind: readFrameKind(r),
    size: r.u8(),
    rotation: r.u8(),
    origin: readBlockPos(r),
    key: readBlockPos(r),
    sockets: r.vec(() => r.option(() => r.string())),
    reads: r.vec(() => r.string()),
    fizzles: r.vec(() => readFizzled(r)),
    status: readFrameStatus(r),
    element: readElement(r),
    rate: r.fixed(),
    pool: r.option(() => readBlockPos(r)),
    owner: r.option(() => readPlayerId(r)),
    delay: r.u32(),
  };
}

function writeFizzled(w: Writer, v: Fizzled): void {
  w.string(v.word);
  writeFizzle(w, v.why);
}

function readFizzled(r: Reader): Fizzled {
  return {
    word: r.string(),
    why: readFizzle(r),
  };
}

function writeFizzle(w: Writer, v: Fizzle): void {
  switch (v.type) {
    case "Twice":
      w.variant(0);
      return;
    case "NotHere":
      w.variant(1);
      return;
    case "NotYet":
      w.variant(2);
      return;
    case "WrongElement":
      w.variant(3);
      return;
    default:
      throw invalidVariant("Fizzle", v);
  }
}

function readFizzle(r: Reader): Fizzle {
  const variant = r.variant();
  switch (variant) {
    case 0:
      return { type: "Twice" };
    case 1:
      return { type: "NotHere" };
    case 2:
      return { type: "NotYet" };
    case 3:
      return { type: "WrongElement" };
    default:
      throw r.unknownVariant("Fizzle");
  }
}

function writeFrameStatus(w: Writer, v: FrameStatus): void {
  switch (v.type) {
    case "Running":
      w.variant(0);
      return;
    case "Dim":
      w.variant(1);
      w.u16(v.permille);
      return;
    case "NotNow":
      w.variant(2);
      writeWhen(w, v.when);
      return;
    case "NoPool":
      w.variant(3);
      return;
    case "Idle":
      w.variant(4);
      return;
    case "Empty":
      w.variant(5);
      return;
    case "Full":
      w.variant(6);
      return;
    case "NoStore":
      w.variant(7);
      return;
    case "StoreFull":
      w.variant(8);
      return;
    default:
      throw invalidVariant("FrameStatus", v);
  }
}

function readFrameStatus(r: Reader): FrameStatus {
  const variant = r.variant();
  switch (variant) {
    case 0:
      return { type: "Running" };
    case 1:
      return {
        type: "Dim",
        permille: r.u16(),
      };
    case 2:
      return {
        type: "NotNow",
        when: readWhen(r),
      };
    case 3:
      return { type: "NoPool" };
    case 4:
      return { type: "Idle" };
    case 5:
      return { type: "Empty" };
    case 6:
      return { type: "Full" };
    case 7:
      return { type: "NoStore" };
    case 8:
      return { type: "StoreFull" };
    default:
      throw r.unknownVariant("FrameStatus");
  }
}

function writeWhen(w: Writer, v: When): void {
  switch (v.type) {
    case "AtNight":
      w.variant(0);
      return;
    case "WhenFull":
      w.variant(1);
      return;
    default:
      throw invalidVariant("When", v);
  }
}

function readWhen(r: Reader): When {
  const variant = r.variant();
  switch (variant) {
    case 0:
      return { type: "AtNight" };
    case 1:
      return { type: "WhenFull" };
    default:
      throw r.unknownVariant("When");
  }
}

function writeFramesView(w: Writer, v: FramesView): void {
  w.vec(v.frames, (x) => writeFrameGlow(w, x));
  w.vec(v.pools, (x) => writePoolGlow(w, x));
  w.vec(v.lines, (x) => writeLineRate(w, x));
}

function readFramesView(r: Reader): FramesView {
  return {
    frames: r.vec(() => readFrameGlow(r)),
    pools: r.vec(() => readPoolGlow(r)),
    lines: r.vec(() => readLineRate(r)),
  };
}

function writeFrameGlow(w: Writer, v: FrameGlow): void {
  writeBlockPos(w, v.origin);
  w.u16(v.frame);
  writeFrameKind(w, v.kind);
  w.u8(v.rotation);
  writeElement(w, v.element);
  w.u8(v.level);
  w.bool(v.armed);
  w.u8(v.fizzled);
}

function readFrameGlow(r: Reader): FrameGlow {
  return {
    origin: readBlockPos(r),
    frame: r.u16(),
    kind: readFrameKind(r),
    rotation: r.u8(),
    element: readElement(r),
    level: r.u8(),
    armed: r.bool(),
    fizzled: r.u8(),
  };
}

function writePoolGlow(w: Writer, v: PoolGlow): void {
  writeBlockPos(w, v.pos);
  writeElement(w, v.element);
  writeLinearAmount(w, v.amount);
  w.u32(v.cap);
}

function readPoolGlow(r: Reader): PoolGlow {
  return {
    pos: readBlockPos(r),
    element: readElement(r),
    amount: readLinearAmount(r),
    cap: r.u32(),
  };
}

function writeLineRate(w: Writer, v: LineRate): void {
  writeBlockPos(w, v.pool);
  writeBlockPos(w, v.user);
  w.bool(v.into);
  w.u8(v.level);
}

function readLineRate(r: Reader): LineRate {
  return {
    pool: readBlockPos(r),
    user: readBlockPos(r),
    into: r.bool(),
    level: r.u8(),
  };
}

function writeRuneforgeView(w: Writer, v: RuneforgeView): void {
  w.bool(v.standing);
  w.vec(v.pools, (x) => writeForgePool(w, x));
  w.option(v.slot, (x) => writeChargeSlotView(w, x));
  w.option(v.stall, (x) => writeStallCause(w, x));
  w.u8(v.sockets);
}

function readRuneforgeView(r: Reader): RuneforgeView {
  return {
    standing: r.bool(),
    pools: r.vec(() => readForgePool(r)),
    slot: r.option(() => readChargeSlotView(r)),
    stall: r.option(() => readStallCause(r)),
    sockets: r.u8(),
  };
}

function writeForgePool(w: Writer, v: ForgePool): void {
  writeElement(w, v.element);
  writeBlockPos(w, v.pos);
  w.bool(v.usable);
}

function readForgePool(r: Reader): ForgePool {
  return {
    element: readElement(r),
    pos: readBlockPos(r),
    usable: r.bool(),
  };
}

function writeChargeSlotView(w: Writer, v: ChargeSlotView): void {
  w.u32(v.id);
  writeNameId(w, v.item);
  w.option(v.rune, (x) => w.string(x));
  w.option(v.element, (x) => writeElement(w, x));
  writePlayerId(w, v.owner);
  writeLinearAmount(w, v.charge);
  w.u32(v.cap);
  w.vec(v.words, (x) => w.string(x));
}

function readChargeSlotView(r: Reader): ChargeSlotView {
  return {
    id: r.u32(),
    item: readNameId(r),
    rune: r.option(() => r.string()),
    element: r.option(() => readElement(r)),
    owner: readPlayerId(r),
    charge: readLinearAmount(r),
    cap: r.u32(),
    words: r.vec(() => r.string()),
  };
}

function writeToolView(w: Writer, v: ToolView): void {
  w.u32(v.id);
  writeNameId(w, v.item);
  w.option(v.rune, (x) => w.string(x));
  w.u32(v.charge);
  w.u32(v.cap);
  w.vec(v.words, (x) => w.string(x));
  w.option(v.charm, (x) => writeCharmInfo(w, x));
  w.option(v.power, (x) => writeToolPower(w, x));
}

function readToolView(r: Reader): ToolView {
  return {
    id: r.u32(),
    item: readNameId(r),
    rune: r.option(() => r.string()),
    charge: r.u32(),
    cap: r.u32(),
    words: r.vec(() => r.string()),
    charm: r.option(() => readCharmInfo(r)),
    power: r.option(() => readToolPower(r)),
  };
}

function writeToolPower(w: Writer, v: ToolPower): void {
  switch (v.type) {
    case "Smelts":
      w.variant(0);
      return;
    case "Reach":
      w.variant(1);
      return;
    case "Glides":
      w.variant(2);
      return;
    case "Breathes":
      w.variant(3);
      return;
    case "Echoes":
      w.variant(4);
      return;
    case "Cushions":
      w.variant(5);
      return;
    case "Sweeps":
      w.variant(6);
      return;
    default:
      throw invalidVariant("ToolPower", v);
  }
}

function readToolPower(r: Reader): ToolPower {
  const variant = r.variant();
  switch (variant) {
    case 0:
      return { type: "Smelts" };
    case 1:
      return { type: "Reach" };
    case 2:
      return { type: "Glides" };
    case 3:
      return { type: "Breathes" };
    case 4:
      return { type: "Echoes" };
    case 5:
      return { type: "Cushions" };
    case 6:
      return { type: "Sweeps" };
    default:
      throw r.unknownVariant("ToolPower");
  }
}

function writeScrollView(w: Writer, v: ScrollView): void {
  w.u32(v.id);
  w.string(v.text);
  w.string(v.frame);
  w.vec(v.words, (x) => w.string(x));
}

function readScrollView(r: Reader): ScrollView {
  return {
    id: r.u32(),
    text: r.string(),
    frame: r.string(),
    words: r.vec(() => r.string()),
  };
}

function writeKinCardView(w: Writer, v: KinCardView): void {
  w.u64(v.herd);
  w.u8(v.member);
  w.u32(v.species);
  w.bool(v.party);
  w.option(v.restingUntil, (x) => w.u64(x));
  w.u32(v.bond);
  w.u64(v.at);
  w.option(v.fullAt, (x) => w.u64(x));
  w.vec(v.words, (x) => writeKinWordView(w, x));
  w.string(v.cosmetic);
  w.option(v.hearth, (x) => writeBlockPos(w, x));
  w.u32(v.manaNow);
  w.u32(v.manaThen);
  w.u8(v.birthplace);
  w.u8(v.traits);
  w.u8(v.homed);
  w.u8(v.room);
  w.bool(v.rejoins);
}

function readKinCardView(r: Reader): KinCardView {
  return {
    herd: r.u64(),
    member: r.u8(),
    species: r.u32(),
    party: r.bool(),
    restingUntil: r.option(() => r.u64()),
    bond: r.u32(),
    at: r.u64(),
    fullAt: r.option(() => r.u64()),
    words: r.vec(() => readKinWordView(r)),
    cosmetic: r.string(),
    hearth: r.option(() => readBlockPos(r)),
    manaNow: r.u32(),
    manaThen: r.u32(),
    birthplace: r.u8(),
    traits: r.u8(),
    homed: r.u8(),
    room: r.u8(),
    rejoins: r.bool(),
  };
}

function writeKinWordView(w: Writer, v: KinWordView): void {
  w.string(v.label);
  w.string(v.about);
  w.bool(v.unlocked);
}

function readKinWordView(r: Reader): KinWordView {
  return {
    label: r.string(),
    about: r.string(),
    unlocked: r.bool(),
  };
}

function writeStoneView(w: Writer, v: StoneView): void {
  w.string(v.name);
  writeBlockPos(w, v.at);
}

function readStoneView(r: Reader): StoneView {
  return {
    name: r.string(),
    at: readBlockPos(r),
  };
}

function writeRelicView(w: Writer, v: RelicView): void {
  w.u32(v.id);
  writeNameId(w, v.item);
  w.u8(v.quality);
  w.string(v.qualityName);
  w.u8(v.floor);
  w.string(v.floorTitle);
  w.option(v.shown, (x) => w.string(x));
  w.u8(v.sealed);
}

function readRelicView(r: Reader): RelicView {
  return {
    id: r.u32(),
    item: readNameId(r),
    quality: r.u8(),
    qualityName: r.string(),
    floor: r.u8(),
    floorTitle: r.string(),
    shown: r.option(() => r.string()),
    sealed: r.u8(),
  };
}

function writeAltarView(w: Writer, v: AltarView): void {
  writeBlockPos(w, v.pos);
  w.string(v.owner);
  w.u8(v.floor);
  w.u8(v.offered);
  w.vec(v.lines, (x) => writeAltarLine(w, x));
  w.u32(v.reroll);
  w.u8(v.keys);
  w.u8(v.fedBy);
  w.bool(v.framed);
  w.vec(v.givers, (x) => w.string(x));
}

function readAltarView(r: Reader): AltarView {
  return {
    pos: readBlockPos(r),
    owner: r.string(),
    floor: r.u8(),
    offered: r.u8(),
    lines: r.vec(() => readAltarLine(r)),
    reroll: r.u32(),
    keys: r.u8(),
    fedBy: r.u8(),
    framed: r.bool(),
    givers: r.vec(() => r.string()),
  };
}

function writeAltarLine(w: Writer, v: AltarLine): void {
  writeNameId(w, v.item);
  w.u32(v.need);
  w.u32(v.have);
  w.string(v.hint);
}

function readAltarLine(r: Reader): AltarLine {
  return {
    item: readNameId(r),
    need: r.u32(),
    have: r.u32(),
    hint: r.string(),
  };
}

